# find repeated k-mers (say 12+)
from collections import defaultdict
def repeat_finder(seq, k=12, mincount=2):
    d = defaultdict(list)
    for i in range(len(seq)-k+1):
        d[seq[i:i+k]].append(i)
    reps = {m:v for m,v in d.items() if len(v)>=mincount}
    return reps

reps = repeat_finder(seq, 20, 2)
print("number of 20-mers appearing 2+ times:", len(reps))
for m,v in sorted(reps.items(), key=lambda x:-len(x[1]))[:20]:
    print(v, m)

seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">")).upper()
comp = str.maketrans("ACGT","TGCA")
rc = lambda s: s.translate(comp)[::-1]

def orfs(seq, minaa=50):
    res=[]
    for strand,s in [(1,seq),(-1,rc(seq))]:
        for f in range(3):
            i=f
            while i < len(s)-2:
                if s[i:i+3]=="ATG":
                    j=i
                    while j < len(s)-2:
                        cod=s[j:j+3]
                        if cod in ("TAA","TAG","TGA"):
                            break
                        j+=3
                    if j-i>=minaa*3:
                        res.append((strand,f,i,j+3,(j-i)//3))
                    i=j+3 if j<len(s)-2 else j+1
                else:
                    i+=3
    return res

