seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">")).upper()
n=len(seq)
k=12
idx={}
for i in range(n-k+1):
    idx.setdefault(seq[i:i+k],[]).append(i)

seeds=[]
for m,pos in idx.items():
    if len(pos)>1:
        for a in range(len(pos)):
            for b in range(a+1,len(pos)):
                seeds.append((pos[a],pos[b]))
print("seed pairs:",len(seeds))
# merge/merge seeds that are collinear (same diagonal) 
from collections import defaultdict
diag=defaultdict(list)
for a,b in seeds:
    diag[b-a].append((a,b))
# cluster consecutive seeds on same diagonal
clusters=[]
for d,lst in diag.items():
    lst.sort()
    cur=[lst[0]]
    for x in lst[1:]:
        if x[0]-cur[-1][0]<=k:
            cur.append(x)
        else:
            clusters.append((d,cur[0][0],cur[-1][0]+k))
            cur=[x]
    clusters.append((d,cur[0][0],cur[-1][0]+k))
clusters=[c for c in clusters if c[2]-c[1]>=20]
clusters.sort(key=lambda x:-(x[2]-x[1]))
for d,a,b in clusters[:20]:
    print(f"diag {d:+5d}: {a+1}-{b} vs {a+1+d}-{b+d}  len {b-a}")

import re
seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">")).upper()
# long homopurine / homopyrimidine
best=[]
for m in re.finditer(r'[AG]{12,}', seq):
    best.append((m.start()+1,m.end(),m.group()))
for m in re.finditer(r'[CT]{12,}', seq):
    best.append((m.start()+1,m.end(),m.group()))
print("homopurine/pyrimidine tracts >=12:", len(best))
for b in best[:20]: print("  ",b)

# dinucleotide repeat tracts (>=6 units)
print("\nDinucleotide tracts >=6:")
for u in ['AT','TA','CG','GC','AC','CA','GT','TG','AG','GA','CT','TC']:
    for m in re.finditer('(%s){6,}'%u, seq):
        print("  ",u,m.start()+1,m.end())

